/**
 * ArvoDrawer -- vanilla JS implementation.
 *
 * Viewport-anchored slide-in overlay panel. Always portaled (default
 * `document.body`, configurable container) and always overlay -- there
 * is no layout/pinned mode (use `ArvoSidePanel` when pinning into the
 * layout is meaningful). Composes the same content shell as
 * `ArvoSidePanel` (header, sticky pre-body region, scrollable body,
 * optional items+filter pipeline, footer) via the shared `panel-shell`
 * pattern, and adds Drawer-only positional concerns: portal mounting,
 * optional backdrop, scroll lock, focus trap, slide-in animation, and
 * Escape / mask-click dismissal.
 *
 * The `element` arg passed to `initialize()` is a marker / cleanup anchor.
 * The visual root (`.arvo-drw` host + optional `__backdrop` sibling) is
 * portaled to `options.container || document.body`.
 *
 * See React parity reference at packages/react/src/components/Drawer/Drawer.tsx.
 */

import {
  createBackdropManager,
  createFocusTrap,
  enter,
  exit,
  lockPageScroll,
} from '@arvo/core';
import type { BackdropManager, FocusTrap, ListItemBase } from '@arvo/core';
import {
  type PanelShellInstance,
  type PanelShellOptions,
  type ArvoPanelHeaderAction,
  type ArvoPanelStickyHeaderConfig,
  type ArvoPanelBannerConfig,
  type ArvoPanelInfoConfig,
  type ArvoPanelAction,
} from '@arvo/utils';
import { createPanelShell } from '../PanelShell/PanelShell';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type ArvoDrawerSide = 'left' | 'right' | 'top' | 'bottom';
export type ArvoDrawerCloseReason =
  | 'escape'
  | 'mask-click'
  | 'close-button'
  | 'programmatic';
export type ArvoDrawerMaskVariant = 'light' | 'dark';

export interface ArvoDrawerMaskConfig {
  variant?: ArvoDrawerMaskVariant;
  opacity?: number;
  blur?: number;
  closeOnClick?: boolean;
}

export interface ArvoDrawerOptions<T extends ListItemBase = ListItemBase> {
  // -- Positional / portal -------------------------------------------------
  side?: ArvoDrawerSide;
  container?: HTMLElement | (() => HTMLElement) | null;

  // -- Open / close --------------------------------------------------------
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onOpen?: () => boolean | void;
  onClose?: (reason: ArvoDrawerCloseReason) => boolean | void;

  // -- Mask / dismissal ----------------------------------------------------
  hasMask?: boolean | ArvoDrawerMaskConfig;
  closeOnEscape?: boolean;
  closeOnMaskClick?: boolean;
  lockScroll?: boolean | 'auto';

  // -- Sizing --------------------------------------------------------------
  width?: string | number;
  minWidth?: string | number;
  maxWidth?: string | number;
  height?: string | number | null;

  // -- Animation -----------------------------------------------------------
  animationDuration?: number;

  // -- A11y / styling ------------------------------------------------------
  ariaLabel?: string;
  ariaLabelledBy?: string;
  className?: string;

  // -- State ---------------------------------------------------------------
  isClosable?: boolean;
  isDisabled?: boolean;
  isLoading?: boolean;

  // -- Forwarded to PanelShell ---------------------------------------------
  title?: string | null;
  hasHeader?: boolean;
  hasBackButton?: boolean;
  onBack?: () => void;
  headerActions?: ArvoPanelHeaderAction[];
  stickyHeader?: ArvoPanelStickyHeaderConfig | false;
  items?: T[];
  getItemId?: (item: T) => string;
  filterKeys?: Array<keyof T & string>;
  getItemSearchText?: (item: T) => string;
  renderItem?: (item: T, el: HTMLElement) => void;
  itemsRole?: 'listbox' | 'list' | 'menu';
  actions?: ArvoPanelAction[] | false;
  hasFooter?: boolean;
}

// ---------------------------------------------------------------------------
// Re-exports of panel-shell types (consumer convenience)
// ---------------------------------------------------------------------------

export type {
  ArvoPanelHeaderAction,
  ArvoPanelStickyHeaderConfig,
  ArvoPanelBannerConfig,
  ArvoPanelInfoConfig,
  ArvoPanelAction,
};

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_LIGHT_OPACITY = 0.32;
const DEFAULT_DARK_OPACITY = 0.5;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function toCssLength(
  value: string | number | null | undefined,
): string | null {
  if (value === null || value === undefined) return null;
  return typeof value === 'number' ? `${value}px` : value;
}

interface ResolvedMask {
  hasMask: boolean;
  variant: ArvoDrawerMaskVariant;
  opacity: number;
  blur: number;
  closeOnClick: boolean;
}

function resolveMask(
  hasMask: boolean | ArvoDrawerMaskConfig | undefined,
  closeOnMaskClickProp: boolean,
): ResolvedMask {
  // Default (undefined) and explicit `false` both render no mask. Consumers
  // opt in to a backdrop by passing `hasMask: true` or a mask config object.
  if (hasMask === undefined || hasMask === false) {
    return {
      hasMask: false,
      variant: 'light',
      opacity: 0,
      blur: 0,
      closeOnClick: false,
    };
  }
  if (hasMask === true) {
    return {
      hasMask: true,
      variant: 'light',
      opacity: DEFAULT_LIGHT_OPACITY,
      blur: 0,
      closeOnClick: closeOnMaskClickProp,
    };
  }
  const variant = hasMask.variant ?? 'light';
  const opacity =
    hasMask.opacity ??
    (variant === 'dark' ? DEFAULT_DARK_OPACITY : DEFAULT_LIGHT_OPACITY);
  return {
    hasMask: true,
    variant,
    opacity,
    blur: hasMask.blur ?? 0,
    closeOnClick: hasMask.closeOnClick ?? closeOnMaskClickProp,
  };
}

function resolveSide(side: ArvoDrawerSide | undefined): 'left' | 'right' {
  const s = side ?? 'right';
  if (s === 'top' || s === 'bottom') {
    if (typeof process !== 'undefined' && process.env.NODE_ENV !== 'production') {
      console.warn(
        `[ArvoDrawer] side='${s}' not yet implemented; using 'right'.`,
      );
    }
    return 'right';
  }
  return s;
}

function resolveContainer(
  container: HTMLElement | (() => HTMLElement) | null | undefined,
): HTMLElement {
  if (container == null) return document.body;
  if (typeof container === 'function') return container();
  return container;
}

const HOST_CLASSES = [
  'arvo-drw',
  'arvo-drw--side-left',
  'arvo-drw--side-right',
  'arvo-drw--side-top',
  'arvo-drw--side-bottom',
  'arvo-drw--with-mask',
  'arvo-drw--mask-light',
  'arvo-drw--mask-dark',
  'open',
  'loading',
  'is-disabled',
  'arvo-enter-from',
  'arvo-enter-active',
  'arvo-enter-to',
  'arvo-exit-from',
  'arvo-exit-active',
  'arvo-exit-to',
];

// ---------------------------------------------------------------------------
// Class
// ---------------------------------------------------------------------------

export class ArvoDrawer<T extends ListItemBase = ListItemBase> {
  private _options: ArvoDrawerOptions<T>;
  /** Consumer-provided marker element. NOT used as the visual root. */
  private _markerEl: HTMLElement;
  /** The portaled `.arvo-drw` host (built by this class, appended to container). */
  private _host: HTMLElement;
  private _paneEl: HTMLElement;
  private _container: HTMLElement;

  private _side: 'left' | 'right';
  private _mask: ResolvedMask;
  private _closeOnEscape: boolean;
  private _lockScrollResolved: boolean;

  private _isOpenState: boolean;
  private _isDisabled: boolean;
  private _isLoading: boolean;

  /** Public for parity with React's PanelShellHandle delegate access. */
  shell!: PanelShellInstance<T>;

  private _backdropManager: BackdropManager | null = null;
  private _backdropEl: HTMLElement | null = null;
  private _backdropMouseDown: ((e: MouseEvent) => void) | null = null;

  private _focusTrap: FocusTrap | null = null;
  private _prevFocusEl: HTMLElement | null = null;
  private _scrollUnlock: (() => void) | null = null;

  private _escapeListener: ((e: KeyboardEvent) => void) | null = null;
  private _shellEventBindings: Array<{
    src: string;
    handler: (e: Event) => void;
  }> = [];

  private _destroyed = false;
  private _isMounted = false;

  static initialize<T extends ListItemBase = ListItemBase>(
    element: HTMLElement,
    options: ArvoDrawerOptions<T> = {},
  ): ArvoDrawer<T> {
    return new ArvoDrawer<T>(element, options);
  }

  constructor(element: HTMLElement, options: ArvoDrawerOptions<T> = {}) {
    this._options = { ...options };
    this._markerEl = element;

    this._side = resolveSide(options.side);
    this._mask = resolveMask(options.hasMask, options.closeOnMaskClick !== false);
    this._closeOnEscape = options.closeOnEscape !== false;
    this._lockScrollResolved =
      options.lockScroll === undefined || options.lockScroll === 'auto'
        ? this._mask.hasMask
        : options.lockScroll === true;

    this._isOpenState = options.isOpen ?? options.defaultOpen ?? false;
    this._isDisabled = !!options.isDisabled;
    this._isLoading = !!options.isLoading;

    this._container = resolveContainer(options.container);

    // Build the portaled host + __pane.
    this._host = document.createElement('div');
    this._paneEl = document.createElement('div');
    this._paneEl.className = 'arvo-drw__pane';
    this._host.appendChild(this._paneEl);

    this._applyClasses();
    this._applyStyleVars();
    this._applyAria();

    // Compose the panel-shell into __pane.
    const contentProps: PanelShellOptions<T> = {
      title: options.title ?? null,
      hasHeader: options.hasHeader,
      hasBackButton: options.hasBackButton,
      onBack: options.onBack,
      headerActions: options.headerActions,
      stickyHeader: options.stickyHeader,
      items: options.items,
      getItemId: options.getItemId,
      filterKeys: options.filterKeys,
      getItemSearchText: options.getItemSearchText,
      renderItem: options.renderItem,
      itemsRole: options.itemsRole,
      actions: options.actions,
      hasFooter: options.hasFooter,
      isClosable: options.isClosable !== false,
      onClose: () => {
        void this.close('close-button');
      },
      isClosableCount: options.isClosable !== false ? 1 : 0,
    };
    this.shell = createPanelShell<T>({
      parentBlock: 'arvo-drw',
      parent: this._paneEl,
      options: contentProps,
    });

    // Apply initial loading / disabled state. The shell delegate writes
    // is-disabled / loading + aria-busy / aria-disabled to __pane. Mirror
    // the BEM-block state classes on the host so SCSS `&.is-disabled` and
    // descriptor stateClasses on `.arvo-drw` both match.
    if (this._isLoading) {
      this.shell.loading(true);
      this._host.classList.add('loading');
    }
    if (this._isDisabled) {
      this.shell.disabled(true);
      this._host.classList.add('is-disabled');
    }

    // Re-emit shell events under the drw:* prefix.
    this._wireShellEventReemit();

    // Honor initial open state (without animation -- consumers calling
    // open() later get the slide-in).
    if (this._isOpenState) {
      this._mountToContainer();
      if (this._mask.hasMask) this._showBackdrop();
      this._host.classList.add('open');
      this._applyAria();
      if (this._lockScrollResolved) this._scrollUnlock = lockPageScroll();
      // Open lifecycle side effects that the open() path also performs.
      // Without these, a Drawer constructed with defaultOpen: true would
      // be visible but unable to dismiss via Escape and would not have an
      // active focus trap.
      if (this._closeOnEscape) this._setupEscapeListener();
      if (!this._isDisabled) {
        this._focusTrap = createFocusTrap();
        this._focusTrap.activate({
          container: this._paneEl,
          initialFocus: 'first',
          returnFocusOnDeactivate: false,
          escapeDeactivates: false,
          allowOutsideClick: true,
        });
      }
    }
  }

  // -------------------------------------------------------------------------
  // Public API -- lifecycle
  // -------------------------------------------------------------------------

  async open(): Promise<void> {
    if (this._destroyed) return;
    if (this._isOpenState) return;
    if (this._options.onOpen?.() === false) return;

    this._prevFocusEl =
      (document.activeElement as HTMLElement | null) ?? null;
    this._isOpenState = true;
    this._mountToContainer();

    if (this._mask.hasMask) this._showBackdrop();
    if (this._lockScrollResolved) this._scrollUnlock = lockPageScroll();

    this._host.classList.add('open');
    this._applyAria();

    if (this._closeOnEscape) this._setupEscapeListener();

    await enter({ element: this._host, type: 'fade' });

    // Activate focus trap AFTER slide-in completes.
    if (!this._isDisabled) {
      this._focusTrap = createFocusTrap();
      this._focusTrap.activate({
        container: this._paneEl,
        initialFocus: 'first',
        returnFocusOnDeactivate: false,
        escapeDeactivates: false,
        allowOutsideClick: true,
      });
    }

    this._paneEl.dispatchEvent(
      new CustomEvent('drw:open', { bubbles: true }),
    );
    this._options.onOpenChange?.(true);
  }

  async close(reason: ArvoDrawerCloseReason = 'programmatic'): Promise<void> {
    if (this._destroyed) return;
    if (!this._isOpenState) return;
    const cancelled =
      this._options.onClose !== undefined &&
      this._options.onClose(reason) === false;
    if (cancelled) return;

    // Deactivate trap synchronously BEFORE slide-out begins.
    this._focusTrap?.deactivate();
    this._focusTrap = null;

    await exit({ element: this._host, type: 'fade' });

    this._host.classList.remove('open');
    this._isOpenState = false;
    this._applyAria();

    this._teardownEscapeListener();

    if (this._mask.hasMask) this._hideBackdrop();

    if (this._scrollUnlock) {
      this._scrollUnlock();
      this._scrollUnlock = null;
    }

    // Restore focus.
    const prev = this._prevFocusEl;
    this._prevFocusEl = null;
    if (prev && typeof prev.focus === 'function') {
      try {
        prev.focus({ preventScroll: true });
      } catch {
        /* element may have been removed; swallow */
      }
    }

    this._paneEl.dispatchEvent(
      new CustomEvent('drw:close', {
        bubbles: true,
        detail: { reason },
      }),
    );
    this._options.onOpenChange?.(false);
  }

  toggle(): void {
    if (this._isOpenState) void this.close('programmatic');
    else void this.open();
  }

  isOpen(): boolean {
    return this._isOpenState;
  }

  // -------------------------------------------------------------------------
  // Public API -- panel-shell delegates
  // -------------------------------------------------------------------------

  setItems(items: T[]): void {
    this.shell.setItems(items);
  }

  setStickyHeader(config: ArvoPanelStickyHeaderConfig | false): void {
    this.shell.setStickyHeader(config);
  }

  setHeaderActions(actions: ArvoPanelHeaderAction[]): void {
    this.shell.setHeaderActions(actions);
  }

  setActions(actions: ArvoPanelAction[] | false): void {
    this.shell.setActions(actions);
  }

  updateAction(
    id: string,
    patch: Partial<ArvoPanelHeaderAction | ArvoPanelAction>,
  ): void {
    this.shell.updateAction(id, patch);
  }

  search(): string;
  search(query: string): void;
  search(query?: string): string | void {
    if (query === undefined) return (this.shell.search() as string) ?? '';
    this.shell.search(query);
  }

  selectedTab(): string | null;
  selectedTab(id: string): void;
  selectedTab(id?: string): string | null | void {
    if (id === undefined) return (this.shell.selectedTab() as string | null) ?? null;
    this.shell.selectedTab(id);
  }

  setTitle(title: string | null): void {
    this.shell.setTitle(title);
  }

  loading(): boolean;
  loading(state: boolean): void;
  loading(state?: boolean): boolean | void {
    if (state === undefined) return this._isLoading;
    this._isLoading = state;
    this.shell.loading(state);
    this._host.classList.toggle('loading', state);
  }

  disabled(): boolean;
  disabled(state: boolean): void;
  disabled(state?: boolean): boolean | void {
    if (state === undefined) return this._isDisabled;
    this._isDisabled = state;
    this.shell.disabled(state);
    this._host.classList.toggle('is-disabled', state);
  }

  focus(target?: 'first' | 'title' | 'search' | 'list'): void {
    this.shell.focus(target);
  }

  // -------------------------------------------------------------------------
  // Destroy
  // -------------------------------------------------------------------------

  destroy(): void {
    if (this._destroyed) return;
    this._destroyed = true;

    this._focusTrap?.deactivate();
    this._focusTrap = null;

    this._teardownEscapeListener();
    this._teardownShellEventReemit();

    if (this._scrollUnlock) {
      this._scrollUnlock();
      this._scrollUnlock = null;
    }

    if (this._mask.hasMask) this._hideBackdrop();

    this.shell.destroy();

    if (this._host.parentNode) {
      this._host.parentNode.removeChild(this._host);
    }
    this._isMounted = false;

    // Strip our classes from the consumer-owned marker (we never wrote to it
    // beyond what the consumer might infer from a class-name option, but be
    // defensive). The marker stays in place.
    if (this._options.className) {
      this._markerEl.classList.remove(this._options.className);
    }
  }

  // -------------------------------------------------------------------------
  // Private -- DOM
  // -------------------------------------------------------------------------

  private _mountToContainer(): void {
    if (this._isMounted) return;
    this._container.appendChild(this._host);
    this._isMounted = true;
  }

  private _applyClasses(): void {
    HOST_CLASSES.forEach((c) => this._host.classList.remove(c));
    this._host.classList.add('arvo-drw');
    this._host.classList.add(`arvo-drw--side-${this._side}`);
    if (this._mask.hasMask) {
      this._host.classList.add('arvo-drw--with-mask');
      this._host.classList.add(`arvo-drw--mask-${this._mask.variant}`);
    }
    if (this._isOpenState) this._host.classList.add('open');
    if (this._isLoading) this._host.classList.add('loading');
    if (this._isDisabled) this._host.classList.add('is-disabled');
    if (this._options.className) {
      this._host.classList.add(this._options.className);
    }
  }

  private _applyStyleVars(): void {
    const w = toCssLength(this._options.width ?? 320);
    const minW = toCssLength(this._options.minWidth ?? 280);
    const maxW = toCssLength(this._options.maxWidth ?? '80vw');
    if (w) this._host.style.setProperty('--arvo-drw-width', w);
    if (minW) this._host.style.setProperty('--arvo-drw-min-width', minW);
    if (maxW) this._host.style.setProperty('--arvo-drw-max-width', maxW);
    if (this._options.animationDuration) {
      this._host.style.setProperty(
        '--arvo-drw-slide-duration',
        `${this._options.animationDuration}ms`,
      );
    }
  }

  private _applyAria(): void {
    this._paneEl.setAttribute('role', 'dialog');
    this._paneEl.setAttribute(
      'aria-modal',
      this._mask.hasMask ? 'true' : 'false',
    );
    if (!this._isOpenState) {
      this._paneEl.setAttribute('aria-hidden', 'true');
    } else {
      this._paneEl.removeAttribute('aria-hidden');
    }
    if (this._options.ariaLabel && !this._options.title) {
      this._paneEl.setAttribute('aria-label', this._options.ariaLabel);
    }
    if (this._options.ariaLabelledBy) {
      this._paneEl.setAttribute(
        'aria-labelledby',
        this._options.ariaLabelledBy,
      );
    }
  }

  // -------------------------------------------------------------------------
  // Private -- backdrop
  // -------------------------------------------------------------------------

  private _showBackdrop(): void {
    if (this._backdropEl) return;
    if (!this._backdropManager) {
      this._backdropManager = createBackdropManager();
    }
    this._backdropEl = this._backdropManager.show({
      opacity: this._mask.opacity,
      // We handle mask-click ourselves (independent of overlayHub's outside
      // click) so the manager only swallows mousedown when closeOnClick is
      // false. Pass true so the manager doesn't add its blocker.
      closeOnClick: this._mask.closeOnClick,
      animated: true,
      container: this._container,
    });

    // Add the BEM block-element class so SCSS hooks can target it.
    this._backdropEl.classList.add('arvo-drw__backdrop');
    if (this._mask.blur > 0) {
      this._backdropEl.style.backdropFilter = `blur(${this._mask.blur}px)`;
      this._backdropEl.style.setProperty(
        '-webkit-backdrop-filter',
        `blur(${this._mask.blur}px)`,
      );
    }

    // Attach our own mousedown listener so we can fire drw:mask-click
    // BEFORE the close (independent of the manager's closeOnClick flag).
    // For deterministic dismissal, we ignore the manager's outside-click
    // hand-off entirely.
    this._backdropMouseDown = (e: MouseEvent) => {
      // Only direct backdrop clicks (not bubbled from elsewhere).
      if (e.target !== this._backdropEl) return;
      this._paneEl.dispatchEvent(
        new CustomEvent('drw:mask-click', { bubbles: true }),
      );
      if (this._mask.closeOnClick) {
        void this.close('mask-click');
      }
    };
    this._backdropEl.addEventListener('mousedown', this._backdropMouseDown);
  }

  private _hideBackdrop(): void {
    if (this._backdropEl && this._backdropMouseDown) {
      this._backdropEl.removeEventListener(
        'mousedown',
        this._backdropMouseDown,
      );
      this._backdropMouseDown = null;
    }
    this._backdropManager?.hide();
    this._backdropEl = null;
  }

  // -------------------------------------------------------------------------
  // Private -- Escape listener
  // -------------------------------------------------------------------------

  private _setupEscapeListener(): void {
    if (this._escapeListener) return;
    this._escapeListener = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      if (!this._isOpenState) return;
      e.stopPropagation();
      void this.close('escape');
    };
    document.addEventListener('keydown', this._escapeListener, true);
  }

  private _teardownEscapeListener(): void {
    if (this._escapeListener) {
      document.removeEventListener('keydown', this._escapeListener, true);
      this._escapeListener = null;
    }
  }

  // -------------------------------------------------------------------------
  // Private -- shell event re-emit (prefix drw:*)
  // -------------------------------------------------------------------------

  private _wireShellEventReemit(): void {
    // 'close' from the shell fires when the close button is clicked. Our
    // onClose callback already routes to this.close('close-button') which
    // dispatches drw:close. We do NOT re-emit shell 'close' here to avoid
    // duplicate drw:close events.
    const map: Record<string, string> = {
      back: 'drw:back',
      action: 'drw:action',
      'tab-select': 'drw:tab-select',
      search: 'drw:search',
      'item-activate': 'drw:item-activate',
    };
    for (const [src, dest] of Object.entries(map)) {
      const handler = (e: Event) => {
        const ce = e as CustomEvent;
        this._paneEl.dispatchEvent(
          new CustomEvent(dest, { bubbles: true, detail: ce.detail }),
        );
      };
      this._paneEl.addEventListener(src, handler);
      this._shellEventBindings.push({ src, handler });
    }
  }

  private _teardownShellEventReemit(): void {
    for (const { src, handler } of this._shellEventBindings) {
      this._paneEl.removeEventListener(src, handler);
    }
    this._shellEventBindings = [];
  }
}

export default ArvoDrawer;
